// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { predicateInfo } from "../../../main/frontend/graph-explorer/statement-details.ts";

test("predicate descriptions preserve the RDF literal base direction", () => {
  const info = predicateInfo([{
    property: { type: "uri", value: "http://www.w3.org/2000/01/rdf-schema#comment" },
    value: { type: "literal", value: "وصف", "xml:lang": "ar", "its:dir": "rtl" },
  }]);
  assert.deepEqual(info.descriptions, [{ text: "وصف", language: "ar", direction: "rtl" }]);
});
